code.java:
public long factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("factorial is undefined for negative n");
    }
    long result = 1;            // 0! and 1! both fall out of this seed
    for (int k = 2; k <= n; k++) {
        result *= k;            // WARNING: silently overflows for n >= 21
    }
    return result;
}

code.python:
def factorial(self, n: int) -> int:
    if n < 0:
        raise ValueError("factorial is undefined for negative n")
    result = 1                  # 0! and 1! both fall out of this seed
    for k in range(2, n + 1):
        result *= k             # Python ints are unbounded — no overflow
    return result

code.java:
import java.math.BigInteger;

public BigInteger factorial(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("factorial is undefined for negative n");
    }
    BigInteger result = BigInteger.ONE;
    for (int k = 2; k <= n; k++) {
        result = result.multiply(BigInteger.valueOf(k));
    }
    return result;
}

code.python:
def factorial(self, n: int) -> int:
    if n < 0:
        raise ValueError("factorial is undefined for negative n")
    result = 1                  # Python ints are already arbitrary precision
    for k in range(2, n + 1):
        result *= k
    return result

